    if(rand(x,y,seed+702)<.16){data[k]=clamp(data[k]-5,0,255);data[k+1]=clamp(data[k+1]-3,0,255);}
    if(rand(x,y,seed+703)<.12){data[k+1]=clamp(data[k+1]+8,0,255);}
