 const shape={round:[.92,.66],block:[1.08,1.02],wedge:[1.02,.94],plate:[1.34,.54],column:[.76,1.54],shard:[.74,1.56],cluster:[1.28,.74],vein:[1.34,.58]}[family]||[1,1];
